import{c as a,Q as e,j as d,m as i}from"./chunks/framework.CWBTDBPu.js";const u=JSON.parse('{"title":"YuVault 安装部署","description":"","frontmatter":{"title":"YuVault 安装部署"},"headers":[],"relativePath":"plugins/items/yu-vault/install.md","filePath":"plugins/items/yu-vault/install.md"}'),s={name:"plugins/items/yu-vault/install.md"};function l(o,t,r,c,h,n){return e(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="yuvault-安装部署" tabindex="-1">YuVault 安装部署 <a class="header-anchor" href="#yuvault-安装部署" aria-label="Permalink to &quot;YuVault 安装部署&quot;">​</a></h1><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>Java</td><td>Java 8 及以上。源码以 <code>sourceCompatibility = JavaVersion.VERSION_1_8</code> 构建。</td></tr><tr><td>服务端</td><td>Spigot、Paper、Paper 衍生端，以及 Mohist、Arclight、Youer 等兼容 Bukkit API 的混合端。</td></tr><tr><td>Minecraft</td><td>目标适配 <code>1.8.x-1.26.x</code>。源码使用 Spigot API <code>1.8-R0.1-SNAPSHOT</code> 编译。建议在正式服同版本测试后上线。</td></tr><tr><td>数据库</td><td>默认 SQLite；跨服共享或多端同步建议使用 MySQL。</td></tr><tr><td>网络访问</td><td>首次启动会从 Maven 仓库下载运行时依赖；bStats 统计也会尝试访问统计服务。</td></tr></tbody></table><h2 id="兼容范围" tabindex="-1">兼容范围 <a class="header-anchor" href="#兼容范围" aria-label="Permalink to &quot;兼容范围&quot;">​</a></h2><p>YuVault 的环境适配范围与 YuTeleport 保持一致。</p><table tabindex="0"><thead><tr><th>兼容范围</th><th>说明</th></tr></thead><tbody><tr><td>Minecraft 版本</td><td>目标适配 <code>1.8.x-1.26.x</code>。</td></tr><tr><td>Bukkit 系服务端</td><td>Spigot、Paper、Paper 衍生端。</td></tr><tr><td>混合端</td><td>Mohist、Arclight、Youer 等 Bukkit API 混合端。</td></tr><tr><td>Java 运行时</td><td>Java 8 及以上。Java 9+ 如果遇到类加载器反射限制，可按控制台提示添加 <code>--add-opens java.base/java.net=ALL-UNNAMED</code>。</td></tr><tr><td>存储后端</td><td>SQLite 单服文件库；MySQL 跨服共享。</td></tr></tbody></table><h2 id="从源码构建" tabindex="-1">从源码构建 <a class="header-anchor" href="#从源码构建" aria-label="Permalink to &quot;从源码构建&quot;">​</a></h2><p>压缩包内是 Gradle 项目。进入插件源码目录后执行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">gradlew.bat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> shadowJar</span></span></code></pre></div><p>构建完成后通常会在 <code>build/libs/</code> 下生成 <code>YuVault-1.1.0.0-all.jar</code>。发布部署时优先使用 <code>shadowJar</code> 产物，因为 bStats 已随插件打包并重定位。</p><h2 id="部署到服务端" tabindex="-1">部署到服务端 <a class="header-anchor" href="#部署到服务端" aria-label="Permalink to &quot;部署到服务端&quot;">​</a></h2><ol><li>停止服务端。</li><li>将构建出的 <code>YuVault-1.1.0.0-all.jar</code> 或发布版 jar 放入服务端 <code>plugins/</code> 目录。</li><li>启动服务端，等待插件生成 <code>plugins/YuVault/config.yml</code> 与 <code>messages.yml</code>。</li><li>首次启动时确认运行时依赖下载完成，控制台应出现 <code>YuVault 已启用</code>。</li><li>进入游戏执行 <code>/yvault help</code>、<code>/yv help</code> 或 <code>/vault help</code> 检查命令是否注册成功。</li></ol><h2 id="运行时依赖" tabindex="-1">运行时依赖 <a class="header-anchor" href="#运行时依赖" aria-label="Permalink to &quot;运行时依赖&quot;">​</a></h2><p>YuVault 在 <code>onLoad</code> 阶段会把这些依赖下载到 <code>plugins/YuVault/libs/</code> 并注入插件类加载器：</p><table tabindex="0"><thead><tr><th>依赖</th><th>版本</th><th>用途</th></tr></thead><tbody><tr><td>HikariCP</td><td><code>4.0.3</code></td><td>MySQL/SQLite 连接池。</td></tr><tr><td>sqlite-jdbc</td><td><code>3.51.3.0</code></td><td>SQLite 文件数据库驱动。</td></tr><tr><td>mysql-connector-j</td><td><code>9.6.0</code></td><td>MySQL 数据库驱动。</td></tr><tr><td>slf4j-api / slf4j-nop</td><td><code>2.0.17</code></td><td>HikariCP 日志依赖。</td></tr></tbody></table><p>默认会校验远程仓库提供的 SHA-256 或 SHA-1。若服务器无法访问 Maven Central，可手动下载对应 jar 放入 <code>plugins/YuVault/libs/</code> 后重启。</p><h2 id="首次配置检查" tabindex="-1">首次配置检查 <a class="header-anchor" href="#首次配置检查" aria-label="Permalink to &quot;首次配置检查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>默认值</th><th>建议</th></tr></thead><tbody><tr><td><code>storage.type</code></td><td><code>sqlite</code></td><td>单服保持默认；多子服共享改为 <code>mysql</code>。</td></tr><tr><td><code>default-vaults</code></td><td><code>0</code></td><td>权限模式下建议通过 <code>yuvault.vaults.&lt;数量&gt;</code> 发放保险柜数量。</td></tr><tr><td><code>default-slots</code></td><td><code>9</code></td><td>必须是 9 的倍数，最终会被限制在 9-54 格。</td></tr><tr><td><code>slot-mode</code></td><td><code>permission</code></td><td>会员/权限组容量建议保持 <code>permission</code>；固定后台设置可改为 <code>command</code>。</td></tr><tr><td><code>world-control.mode</code></td><td><code>blacklist</code></td><td>将登录服、大厅、活动禁用世界加入列表。</td></tr><tr><td><code>item-control.mode</code></td><td><code>blacklist</code></td><td>保持黑名单，加入高风险方块、特殊容器或不希望跨服转移的物品。</td></tr><tr><td><code>auto-save-interval</code></td><td><code>60</code></td><td>正式服建议保持开启。</td></tr><tr><td><code>library.verify-checksum</code></td><td><code>true</code></td><td>推荐保持开启，避免损坏或被替换的依赖 jar 被加载。</td></tr></tbody></table><h2 id="mysql-跨服共享" tabindex="-1">MySQL 跨服共享 <a class="header-anchor" href="#mysql-跨服共享" aria-label="Permalink to &quot;MySQL 跨服共享&quot;">​</a></h2><p>将 <code>storage.type</code> 改为 <code>mysql</code>，并填写数据库连接参数：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">storage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mysql&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mysql</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3306</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;yuvault&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    username</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;yuvault&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;change-me&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    jdbc-params</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;useSSL=false&amp;allowPublicKeyRetrieval=true&amp;autoReconnect=true&quot;</span></span></code></pre></div><p>上线前建议：</p><ol><li>给 YuVault 单独创建数据库账号。</li><li>确认所有子服使用同一套插件版本与配置版本。</li><li>在测试服创建、打开、缩容、删除保险柜，确认回收箱流程正常。</li><li>对 <code>vaults</code> 与 <code>reclaimed_items</code> 表做定期备份。</li></ol><h2 id="升级已有版本" tabindex="-1">升级已有版本 <a class="header-anchor" href="#升级已有版本" aria-label="Permalink to &quot;升级已有版本&quot;">​</a></h2><p>插件会读取 <code>config-version</code> 和 <code>messages-version</code>，当版本落后时合并默认配置并保留已有值。</p><table tabindex="0"><thead><tr><th>文件</th><th>当前版本</th><th>备份行为</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td><code>2</code></td><td>更新时自动合并缺失配置项。</td></tr><tr><td><code>messages.yml</code></td><td><code>2</code></td><td>更新时自动合并缺失消息项。</td></tr></tbody></table><p>升级建议：</p><ol><li>停服备份 <code>plugins/YuVault/</code>，MySQL 模式下同时备份数据库。</li><li>替换 jar。</li><li>启动一次服务端，让插件自动合并新配置。</li><li>检查控制台是否有依赖加载、数据库连接或配置格式错误。</li><li>执行 <code>/yvault gui</code>、<code>/yvault reclaimed</code>、<code>/yvault reload</code> 和一次管理员打开他人保险柜测试。</li></ol><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><ol><li>停止服务端。</li><li>删除 <code>plugins/</code> 中的 YuVault jar。</li><li>如不再需要数据，删除 <code>plugins/YuVault/</code> 目录。</li><li>MySQL 模式下按需删除 <code>vaults</code> 与 <code>reclaimed_items</code> 表。</li></ol>`,30)])])}const k=a(s,[["render",l]]);export{u as __pageData,k as default};
